window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2023-national_paper_a_science"]=[{"id":"2023-national_paper_a_science-q01","paperId":"2023-national_paper_a_science","number":1,"type":"single","score":5,"lessonIds":["1.3"],"difficulty":"基础","hint":"整数除以 3 只有余 0、1、2 三类，M 与 N 分别占余 1、余 2 的两类。","legacy":false,"legacyReason":"","searchText":"设全集 U=\\Z ，集合 M=\\{x\\mid x=3k+1,\\ k\\in \\Z\\} ， N=\\{x\\mid x=3k+2,\\ k\\in \\Z\\} ，则 \\complement_U\\left( M\\cup N \\right) 为（ ） \\{x\\mid x=3k,\\ k\\in \\Z\\} \\{x\\mid x=3k-1,\\ k\\in \\Z\\} \\{x\\mid x=3k-2,\\ k\\in \\Z\\} \\varnothing","questionHtml":"设全集 <span class=\"gk-math\" data-tex=\"U=\\Z\">U=\\Z</span>，集合 <span class=\"gk-math\" data-tex=\"M=\\{x\\mid x=3k+1,\\ k\\in \\Z\\}\">M=\\{x\\mid x=3k+1,\\ k\\in \\Z\\}</span>，<span class=\"gk-math\" data-tex=\"N=\\{x\\mid x=3k+2,\\ k\\in \\Z\\}\">N=\\{x\\mid x=3k+2,\\ k\\in \\Z\\}</span>，则 <span class=\"gk-math\" data-tex=\"\\complement_U\\left( M\\cup N \\right)\">\\complement_U\\left( M\\cup N \\right)</span> 为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{x\\mid x=3k,\\ k\\in \\Z\\}\">\\{x\\mid x=3k,\\ k\\in \\Z\\}</span>","<span class=\"gk-math\" data-tex=\"\\{x\\mid x=3k-1,\\ k\\in \\Z\\}\">\\{x\\mid x=3k-1,\\ k\\in \\Z\\}</span>","<span class=\"gk-math\" data-tex=\"\\{x\\mid x=3k-2,\\ k\\in \\Z\\}\">\\{x\\mid x=3k-2,\\ k\\in \\Z\\}</span>","<span class=\"gk-math\" data-tex=\"\\varnothing\">\\varnothing</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"任取 <span class=\"gk-math\" data-tex=\"x\\in\\Z\">x\\in\\Z</span>，整数 <span class=\"gk-math\" data-tex=\"x\">x</span> 除以 <span class=\"gk-math\" data-tex=\"3\">3</span> 的余数只能为 <span class=\"gk-math\" data-tex=\"0\">0</span>，<span class=\"gk-math\" data-tex=\"1\">1</span> 或 <span class=\"gk-math\" data-tex=\"2\">2</span>，所以 <span class=\"gk-math\" data-tex=\"\\Z=M\\cup N\\cup\\{x\\mid x=3k,\\ k\\in\\Z\\}\">\\Z=M\\cup N\\cup\\{x\\mid x=3k,\\ k\\in\\Z\\}</span>，且这三个集合两两不交. 因此 <span class=\"gk-math\" data-tex=\"\\complement_U\\left(M\\cup N\\right)=\\{x\\mid x=3k,\\ k\\in\\Z\\}\">\\complement_U\\left(M\\cup N\\right)=\\{x\\mid x=3k,\\ k\\in\\Z\\}</span>，故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q02","paperId":"2023-national_paper_a_science","number":2,"type":"single","score":5,"lessonIds":["7.1","7.2"],"difficulty":"基础","hint":"先展开成 2a+(1−a²)i，再让实部等于 2、虚部等于 0。","legacy":false,"legacyReason":"","searchText":"设 a\\in \\R ， (a+\\i)(1-\\i a)=2 ，则 a= （ ） -2 -1 1 2","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a\\in \\R\">a\\in \\R</span>，<span class=\"gk-math\" data-tex=\"(a+\\i)(1-\\i a)=2\">(a+\\i)(1-\\i a)=2</span>，则 <span class=\"gk-math\" data-tex=\"a=\">a=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-2\">-2</span>","<span class=\"gk-math\" data-tex=\"-1\">-1</span>","<span class=\"gk-math\" data-tex=\"1\">1</span>","<span class=\"gk-math\" data-tex=\"2\">2</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"(a+\\i)(1-\\i a)=2a+\\i(1-a^2)=2\">(a+\\i)(1-\\i a)=2a+\\i(1-a^2)=2</span>，比较实部与虚部得 <span class=\"gk-math\" data-tex=\"2a=2\">2a=2</span>，<span class=\"gk-math\" data-tex=\"1-a^2=0\">1-a^2=0</span>. 由 <span class=\"gk-math\" data-tex=\"a\\in\\R\">a\\in\\R</span> 可得 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span>，故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q03","paperId":"2023-national_paper_a_science","number":3,"type":"single","score":5,"lessonIds":["e2-4.1"],"difficulty":"进阶","hint":"这是超出当前五册的程序框图题；从 n=3、A=1、B=2、k=1 开始，先更新 A，再用新的 A 更新 B，记录三轮结果。","legacy":true,"legacyReason":"","searchText":"执行如图的程序框图，则输出的 B= （ ） 21 34 55 89","questionHtml":"执行如图的程序框图，则输出的 <span class=\"gk-math\" data-tex=\"B=\">B=</span>（ ）<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,407px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/national_paper_a_science/q3_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/national_paper_a_science/q3_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"391\" height=\"542\" style=\"aspect-ratio:391/542;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["21","34","55","89"],"answerHtml":"B","answerKey":"B","solutionHtml":"程序开始时 <span class=\"gk-math\" data-tex=\"A=1\">A=1</span>，<span class=\"gk-math\" data-tex=\"B=2\">B=2</span>，<span class=\"gk-math\" data-tex=\"k=1\">k=1</span>，且循环条件为 <span class=\"gk-math\" data-tex=\"k\\leq 3\">k\\leq 3</span>. 第一次循环后 <span class=\"gk-math\" data-tex=\"A=1+2=3\">A=1+2=3</span>，<span class=\"gk-math\" data-tex=\"B=3+2=5\">B=3+2=5</span>，<span class=\"gk-math\" data-tex=\"k=2\">k=2</span>；第二次循环后 <span class=\"gk-math\" data-tex=\"A=3+5=8\">A=3+5=8</span>，<span class=\"gk-math\" data-tex=\"B=8+5=13\">B=8+5=13</span>，<span class=\"gk-math\" data-tex=\"k=3\">k=3</span>；第三次循环后 <span class=\"gk-math\" data-tex=\"A=8+13=21\">A=8+13=21</span>，<span class=\"gk-math\" data-tex=\"B=21+13=34\">B=21+13=34</span>，<span class=\"gk-math\" data-tex=\"k=4\">k=4</span>. 此时循环条件不成立，输出 <span class=\"gk-math\" data-tex=\"B=34\">B=34</span>，故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q04","paperId":"2023-national_paper_a_science","number":4,"type":"single","score":5,"lessonIds":["6.2"],"difficulty":"进阶","hint":"由 c=−a−b 和 |c|²=2 先求 a·b，再把所求夹角的分子与两个模长展开。","legacy":false,"legacyReason":"","searchText":"已知向量 \\bs{a} ， \\bs{b} ， \\bs{c} 满足 \\lvert \\bs{a} \\rvert=\\lvert \\bs{b} \\rvert=1 ， \\lvert \\bs{c} \\rvert=\\sqrt{2} ，且 \\bs{a}+\\bs{b}+\\bs{c}=\\bs{0} ，则 \\cos\\left( \\bs{a}-\\bs{c},\\bs{b}-\\bs{c} \\right)= （ ） -\\frac45 -\\frac25 \\frac25 \\frac45","questionHtml":"已知向量 <span class=\"gk-math\" data-tex=\"\\bs{a}\">\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}\">\\bs{b}</span>，<span class=\"gk-math\" data-tex=\"\\bs{c}\">\\bs{c}</span> 满足 <span class=\"gk-math\" data-tex=\"\\lvert \\bs{a} \\rvert=\\lvert \\bs{b} \\rvert=1\">\\lvert \\bs{a} \\rvert=\\lvert \\bs{b} \\rvert=1</span>，<span class=\"gk-math\" data-tex=\"\\lvert \\bs{c} \\rvert=\\sqrt{2}\">\\lvert \\bs{c} \\rvert=\\sqrt{2}</span>，且 <span class=\"gk-math\" data-tex=\"\\bs{a}+\\bs{b}+\\bs{c}=\\bs{0}\">\\bs{a}+\\bs{b}+\\bs{c}=\\bs{0}</span>，则 <span class=\"gk-math\" data-tex=\"\\cos\\left( \\bs{a}-\\bs{c},\\bs{b}-\\bs{c} \\right)=\">\\cos\\left( \\bs{a}-\\bs{c},\\bs{b}-\\bs{c} \\right)=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"-\\frac45\">-\\frac45</span>","<span class=\"gk-math\" data-tex=\"-\\frac25\">-\\frac25</span>","<span class=\"gk-math\" data-tex=\"\\frac25\">\\frac25</span>","<span class=\"gk-math\" data-tex=\"\\frac45\">\\frac45</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\bs{a}+\\bs{b}+\\bs{c}=\\bs{0}\">\\bs{a}+\\bs{b}+\\bs{c}=\\bs{0}</span> 得 <span class=\"gk-math\" data-tex=\"\\bs{c}=-(\\bs{a}+\\bs{b})\">\\bs{c}=-(\\bs{a}+\\bs{b})</span>. 因为 <span class=\"gk-math\" data-tex=\"\\lvert\\bs{c}\\rvert^2=\\lvert\\bs{a}+\\bs{b}\\rvert^2=\\lvert\\bs{a}\\rvert^2+\\lvert\\bs{b}\\rvert^2+2\\bs{a}\\cdot\\bs{b}\">\\lvert\\bs{c}\\rvert^2=\\lvert\\bs{a}+\\bs{b}\\rvert^2=\\lvert\\bs{a}\\rvert^2+\\lvert\\bs{b}\\rvert^2+2\\bs{a}\\cdot\\bs{b}</span>，所以 <span class=\"gk-math\" data-tex=\"2=1+1+2\\bs{a}\\cdot\\bs{b}\">2=1+1+2\\bs{a}\\cdot\\bs{b}</span>，从而 <span class=\"gk-math\" data-tex=\"\\bs{a}\\cdot\\bs{b}=0\">\\bs{a}\\cdot\\bs{b}=0</span>. 又 <span class=\"gk-math\" data-tex=\"\\bs{a}-\\bs{c}=2\\bs{a}+\\bs{b}\">\\bs{a}-\\bs{c}=2\\bs{a}+\\bs{b}</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}-\\bs{c}=\\bs{a}+2\\bs{b}\">\\bs{b}-\\bs{c}=\\bs{a}+2\\bs{b}</span>，故 <span class=\"gk-math\" data-tex=\"(\\bs{a}-\\bs{c})\\cdot(\\bs{b}-\\bs{c})=(2\\bs{a}+\\bs{b})\\cdot(\\bs{a}+2\\bs{b})=4\">(\\bs{a}-\\bs{c})\\cdot(\\bs{b}-\\bs{c})=(2\\bs{a}+\\bs{b})\\cdot(\\bs{a}+2\\bs{b})=4</span>，并且 <span class=\"gk-math\" data-tex=\"\\lvert\\bs{a}-\\bs{c}\\rvert^2=5\">\\lvert\\bs{a}-\\bs{c}\\rvert^2=5</span>，<span class=\"gk-math\" data-tex=\"\\lvert\\bs{b}-\\bs{c}\\rvert^2=5\">\\lvert\\bs{b}-\\bs{c}\\rvert^2=5</span>. 因此 <span class=\"gk-math\" data-tex=\"\\cos\\left(\\bs{a}-\\bs{c},\\bs{b}-\\bs{c}\\right)=\\dfrac{4}{\\sqrt5\\sqrt5}=\\dfrac45\">\\cos\\left(\\bs{a}-\\bs{c},\\bs{b}-\\bs{c}\\right)=\\dfrac{4}{\\sqrt5\\sqrt5}=\\dfrac45</span>，故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q05","paperId":"2023-national_paper_a_science","number":5,"type":"single","score":5,"lessonIds":["e2-4.3"],"difficulty":"进阶","hint":"由于每项为正，公比 q>0；先把 S₅=5S₃−4 展开成 q 的方程并因式分解。","legacy":false,"legacyReason":"","searchText":"设等比数列 \\{a_n\\} 的各项均为正数，前 n 项和为 S_n ，若 a_1=1 ， S_5=5S_3-4 ，则 S_4= （ ） \\frac{15}{8} \\frac{65}{8} 15 40","questionHtml":"设等比数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的各项均为正数，前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和为 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span>，若 <span class=\"gk-math\" data-tex=\"a_1=1\">a_1=1</span>，<span class=\"gk-math\" data-tex=\"S_5=5S_3-4\">S_5=5S_3-4</span>，则 <span class=\"gk-math\" data-tex=\"S_4=\">S_4=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\frac{15}{8}\">\\frac{15}{8}</span>","<span class=\"gk-math\" data-tex=\"\\frac{65}{8}\">\\frac{65}{8}</span>","15","40"],"answerHtml":"C","answerKey":"C","solutionHtml":"设等比数列的公比为 <span class=\"gk-math\" data-tex=\"q\">q</span>，由各项为正数知 <span class=\"gk-math\" data-tex=\"q&gt;0\">q&gt;0</span>. 因为 <span class=\"gk-math\" data-tex=\"a_1=1\">a_1=1</span>，所以 <span class=\"gk-math\" data-tex=\"S_5=1+q+q^2+q^3+q^4\">S_5=1+q+q^2+q^3+q^4</span>，<span class=\"gk-math\" data-tex=\"5S_3-4=5(1+q+q^2)-4=1+5q+5q^2\">5S_3-4=5(1+q+q^2)-4=1+5q+5q^2</span>. 由题意 <span class=\"gk-math\" data-tex=\"q+q^2+q^3+q^4=5q+5q^2\">q+q^2+q^3+q^4=5q+5q^2</span>，即 <span class=\"gk-math\" data-tex=\"q(q+1)(q-2)(q+2)=0\">q(q+1)(q-2)(q+2)=0</span>. 结合 <span class=\"gk-math\" data-tex=\"q&gt;0\">q&gt;0</span> 得 <span class=\"gk-math\" data-tex=\"q=2\">q=2</span>，所以 <span class=\"gk-math\" data-tex=\"S_4=1+2+2^2+2^3=15\">S_4=1+2+2^2+2^3=15</span>，故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q06","paperId":"2023-national_paper_a_science","number":6,"type":"single","score":5,"lessonIds":["e3-7.1","10.1"],"difficulty":"基础","hint":"先用并事件公式求同时爱好滑冰与滑雪的概率，再除以爱好滑雪的概率 0.5。","legacy":false,"legacyReason":"","searchText":"某地的中学生中有 60% 的同学爱好滑冰，50% 的同学爱好滑雪，70% 的同学爱好滑冰或爱好滑雪. 在该地的中学生中随机调查一位同学，若该同学爱好滑雪，则该同学也爱好滑冰的概率为（ ） 0.8 0.6 0.5 0.4","questionHtml":"某地的中学生中有 60% 的同学爱好滑冰，50% 的同学爱好滑雪，70% 的同学爱好滑冰或爱好滑雪. 在该地的中学生中随机调查一位同学，若该同学爱好滑雪，则该同学也爱好滑冰的概率为（ ）","optionsHtml":["0.8","0.6","0.5","0.4"],"answerHtml":"A","answerKey":"A","solutionHtml":"设爱好滑冰和爱好滑雪分别为事件 <span class=\"gk-math\" data-tex=\"A\">A</span> 和 <span class=\"gk-math\" data-tex=\"B\">B</span>. 由加法公式 <span class=\"gk-math\" data-tex=\"P(A\\cap B)=P(A)+P(B)-P(A\\cup B)=0.6+0.5-0.7=0.4\">P(A\\cap B)=P(A)+P(B)-P(A\\cup B)=0.6+0.5-0.7=0.4</span>. 因此 <span class=\"gk-math\" data-tex=\"P(A\\mid B)=\\dfrac{P(A\\cap B)}{P(B)}=\\dfrac{0.4}{0.5}=0.8\">P(A\\mid B)=\\dfrac{P(A\\cap B)}{P(B)}=\\dfrac{0.4}{0.5}=0.8</span>，故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q07","paperId":"2023-national_paper_a_science","number":7,"type":"single","score":5,"lessonIds":["1.4","5.2"],"difficulty":"基础","hint":"先检查乙是否能推出 sin²α=cos²β，再想甲取平方后是否丢掉了正负号。","legacy":false,"legacyReason":"","searchText":"设甲： \\sin^2\\alpha+\\sin^2\\beta=1 ，乙： \\sin\\alpha+\\cos\\beta=0 . 则（ ） 甲是乙的充分条件但不是必要条件 甲是乙的必要条件但不是充分条件 甲是乙的充要条件 甲既不是乙的充分条件也不是乙的必要条件","questionHtml":"设甲：<span class=\"gk-math\" data-tex=\"\\sin^2\\alpha+\\sin^2\\beta=1\">\\sin^2\\alpha+\\sin^2\\beta=1</span>，乙：<span class=\"gk-math\" data-tex=\"\\sin\\alpha+\\cos\\beta=0\">\\sin\\alpha+\\cos\\beta=0</span>. 则（ ）","optionsHtml":["甲是乙的充分条件但不是必要条件","甲是乙的必要条件但不是充分条件","甲是乙的充要条件","甲既不是乙的充分条件也不是乙的必要条件"],"answerHtml":"B","answerKey":"B","solutionHtml":"若乙成立，则 <span class=\"gk-math\" data-tex=\"\\sin\\alpha=-\\cos\\beta\">\\sin\\alpha=-\\cos\\beta</span>，从而 <span class=\"gk-math\" data-tex=\"\\sin^2\\alpha+\\sin^2\\beta=\\cos^2\\beta+\\sin^2\\beta=1\">\\sin^2\\alpha+\\sin^2\\beta=\\cos^2\\beta+\\sin^2\\beta=1</span>，所以乙是甲成立的充分条件，即甲是乙成立的必要条件. 但取 <span class=\"gk-math\" data-tex=\"\\alpha=\\dfrac{\\pi}{2}\">\\alpha=\\dfrac{\\pi}{2}</span>，<span class=\"gk-math\" data-tex=\"\\beta=0\">\\beta=0</span>，有 <span class=\"gk-math\" data-tex=\"\\sin^2\\alpha+\\sin^2\\beta=1\">\\sin^2\\alpha+\\sin^2\\beta=1</span>，而 <span class=\"gk-math\" data-tex=\"\\sin\\alpha+\\cos\\beta=2\\ne0\">\\sin\\alpha+\\cos\\beta=2\\ne0</span>，所以甲不是乙的充分条件. 故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q08","paperId":"2023-national_paper_a_science","number":8,"type":"single","score":5,"lessonIds":["e1-3.2","e1-2.5"],"difficulty":"进阶","hint":"由 e²=1+b²/a² 先求渐近线斜率，再用圆心到直线距离计算弦长。","legacy":false,"legacyReason":"","searchText":"已知双曲线 C:\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1 （ a>0 ， b>0 ）的离心率为 \\sqrt{5} ， C 的一条渐近线与圆 \\left( x-2 \\right)^2+\\left( y-3 \\right)^2=1 交于 A ， B 两点，则 \\lvert AB \\rvert= （ ） \\frac{\\sqrt{5}}{5} \\frac{2\\sqrt{5}}{5} \\frac{3\\sqrt{5}}{5} \\frac{4\\sqrt{5}}{5}","questionHtml":"已知双曲线 <span class=\"gk-math\" data-tex=\"C:\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1\">C:\\frac{x^2}{a^2}-\\frac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>）的离心率为 <span class=\"gk-math\" data-tex=\"\\sqrt{5}\">\\sqrt{5}</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 的一条渐近线与圆 <span class=\"gk-math\" data-tex=\"\\left( x-2 \\right)^2+\\left( y-3 \\right)^2=1\">\\left( x-2 \\right)^2+\\left( y-3 \\right)^2=1</span> 交于 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 两点，则 <span class=\"gk-math\" data-tex=\"\\lvert AB \\rvert=\">\\lvert AB \\rvert=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{5}}{5}\">\\frac{\\sqrt{5}}{5}</span>","<span class=\"gk-math\" data-tex=\"\\frac{2\\sqrt{5}}{5}\">\\frac{2\\sqrt{5}}{5}</span>","<span class=\"gk-math\" data-tex=\"\\frac{3\\sqrt{5}}{5}\">\\frac{3\\sqrt{5}}{5}</span>","<span class=\"gk-math\" data-tex=\"\\frac{4\\sqrt{5}}{5}\">\\frac{4\\sqrt{5}}{5}</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"由双曲线的离心率得 <span class=\"gk-math\" data-tex=\"5=e^2=1+\\dfrac{b^2}{a^2}\">5=e^2=1+\\dfrac{b^2}{a^2}</span>，所以 <span class=\"gk-math\" data-tex=\"\\dfrac ba=2\">\\dfrac ba=2</span>，其渐近线为 <span class=\"gk-math\" data-tex=\"y=\\pm2x\">y=\\pm2x</span>. 直线 <span class=\"gk-math\" data-tex=\"y=-2x\">y=-2x</span> 到圆心 <span class=\"gk-math\" data-tex=\"(2,3)\">(2,3)</span> 的距离为 <span class=\"gk-math\" data-tex=\"\\dfrac{7}{\\sqrt5}&gt;1\">\\dfrac{7}{\\sqrt5}&gt;1</span>，不与该圆相交，因此题设中的渐近线为 <span class=\"gk-math\" data-tex=\"y=2x\">y=2x</span>. 圆心到直线 <span class=\"gk-math\" data-tex=\"2x-y=0\">2x-y=0</span> 的距离为 <span class=\"gk-math\" data-tex=\"d=\\dfrac{|4-3|}{\\sqrt5}=\\dfrac1{\\sqrt5}\">d=\\dfrac{|4-3|}{\\sqrt5}=\\dfrac1{\\sqrt5}</span>. 由弦长公式 <span class=\"gk-math\" data-tex=\"\\lvert AB\\rvert=2\\sqrt{1-d^2}=2\\sqrt{1-\\dfrac15}=\\dfrac{4\\sqrt5}{5}\">\\lvert AB\\rvert=2\\sqrt{1-d^2}=2\\sqrt{1-\\dfrac15}=\\dfrac{4\\sqrt5}{5}</span>，故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q09","paperId":"2023-national_paper_a_science","number":9,"type":"single","score":5,"lessonIds":["e3-6.2","e3-6.1"],"difficulty":"进阶","hint":"先选五个人中的共同参加者，再从其余四人中有顺序地选星期六、星期日各自的另一人。","legacy":false,"legacyReason":"","searchText":"现有 5 名志愿者报名参加公益活动，在某一星期的星期六，星期日两天，每天从这 5 人中安排 2 人参加公益活动，则恰有 1 人在这两天都参加的不同安排方式共有（ ） 120 种 60 种 30 种 20 种","questionHtml":"现有 5 名志愿者报名参加公益活动，在某一星期的星期六，星期日两天，每天从这 5 人中安排 2 人参加公益活动，则恰有 1 人在这两天都参加的不同安排方式共有（ ）","optionsHtml":["120 种","60 种","30 种","20 种"],"answerHtml":"B","answerKey":"B","solutionHtml":"先选出两天都参加的志愿者，共有 <span class=\"gk-math\" data-tex=\"5\">5</span> 种选法. 固定这名志愿者后，星期六还需从其余 <span class=\"gk-math\" data-tex=\"4\">4</span> 人中选 <span class=\"gk-math\" data-tex=\"1\">1</span> 人，星期日还需从剩余的 <span class=\"gk-math\" data-tex=\"3\">3</span> 人中选 <span class=\"gk-math\" data-tex=\"1\">1</span> 人，才能保证恰有 <span class=\"gk-math\" data-tex=\"1\">1</span> 人两天都参加，因此安排方式共有 <span class=\"gk-math\" data-tex=\"5\\times4\\times3=60\">5\\times4\\times3=60</span> 种，故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q10","paperId":"2023-national_paper_a_science","number":10,"type":"single","score":5,"lessonIds":["5.6","4.5","e2-5.3"],"difficulty":"挑战","hint":"平移后函数是 −sin2x，先用正弦值范围把交点限制在 [−1,3]，再逐段比较曲线与直线。","legacy":false,"legacyReason":"","searchText":"函数 y=f(x) 的图象由函数 y=\\cos\\left( 2x+\\frac{\\pi}{6} \\right) 的图象向左平移 \\frac{\\pi}{6} 个单位长度得到，则 y=f(x) 的图象与直线 y=\\frac12x-\\frac12 的交点个数为（ ） 1 2 3 4","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的图象由函数 <span class=\"gk-math\" data-tex=\"y=\\cos\\left( 2x+\\frac{\\pi}{6} \\right)\">y=\\cos\\left( 2x+\\frac{\\pi}{6} \\right)</span> 的图象向左平移 <span class=\"gk-math\" data-tex=\"\\frac{\\pi}{6}\">\\frac{\\pi}{6}</span> 个单位长度得到，则 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 的图象与直线 <span class=\"gk-math\" data-tex=\"y=\\frac12x-\\frac12\">y=\\frac12x-\\frac12</span> 的交点个数为（ ）","optionsHtml":["1","2","3","4"],"answerHtml":"C","answerKey":"C","solutionHtml":"函数图象向左平移 <span class=\"gk-math\" data-tex=\"\\dfrac\\pi6\">\\dfrac\\pi6</span> 后， <span class=\"gk-math\" data-tex=\"f(x)=\\cos\\left(2\\left(x+\\dfrac\\pi6\\right)+\\dfrac\\pi6\\right)=\\cos\\left(2x+\\dfrac\\pi2\\right)=-\\sin2x\">f(x)=\\cos\\left(2\\left(x+\\dfrac\\pi6\\right)+\\dfrac\\pi6\\right)=\\cos\\left(2x+\\dfrac\\pi2\\right)=-\\sin2x</span>. 令 <span class=\"gk-math\" data-tex=\"h(x)=-\\sin2x-\\dfrac{x-1}{2}\">h(x)=-\\sin2x-\\dfrac{x-1}{2}</span>，交点的横坐标就是 <span class=\"gk-math\" data-tex=\"h(x)=0\">h(x)=0</span> 的根. 由 <span class=\"gk-math\" data-tex=\"-1\\leq -\\sin2x\\leq1\">-1\\leq -\\sin2x\\leq1</span> 可知根必满足 <span class=\"gk-math\" data-tex=\"-1\\leq x\\leq3\">-1\\leq x\\leq3</span>.<br><br>在 <span class=\"gk-math\" data-tex=\"[0,\\dfrac\\pi4]\">[0,\\dfrac\\pi4]</span> 上，<span class=\"gk-math\" data-tex=\"h&#x27;(x)=-2\\cos2x-\\dfrac12&lt;0\">h&#x27;(x)=-2\\cos2x-\\dfrac12&lt;0</span>，且 <span class=\"gk-math\" data-tex=\"h(0)=\\dfrac12&gt;0\">h(0)=\\dfrac12&gt;0</span>，<span class=\"gk-math\" data-tex=\"h(\\dfrac\\pi4)=-\\dfrac12-\\dfrac\\pi8&lt;0\">h(\\dfrac\\pi4)=-\\dfrac12-\\dfrac\\pi8&lt;0</span>，故有且仅有一个根. 在 <span class=\"gk-math\" data-tex=\"[\\dfrac\\pi4,\\dfrac\\pi2]\">[\\dfrac\\pi4,\\dfrac\\pi2]</span> 上，<span class=\"gk-math\" data-tex=\"h&#x27;&#x27;(x)=4\\sin2x&gt;0\">h&#x27;&#x27;(x)=4\\sin2x&gt;0</span>，<span class=\"gk-math\" data-tex=\"h&#x27;\">h&#x27;</span> 只变号一次，函数先减后增，而 <span class=\"gk-math\" data-tex=\"h(\\dfrac\\pi4)&lt;0\">h(\\dfrac\\pi4)&lt;0</span>，<span class=\"gk-math\" data-tex=\"h(\\dfrac\\pi2)=\\dfrac{1-\\frac{\\pi}{2}}{2}&lt;0\">h(\\dfrac\\pi2)=\\dfrac{1-\\frac{\\pi}{2}}{2}&lt;0</span>，故没有根.<br><br>当 <span class=\"gk-math\" data-tex=\"x\\in[-1,0]\">x\\in[-1,0]</span> 时，<span class=\"gk-math\" data-tex=\"\\sin2x\\leq0\">\\sin2x\\leq0</span>，所以 <span class=\"gk-math\" data-tex=\"h(x)=-\\sin2x-\\dfrac{x-1}{2}&gt;0\">h(x)=-\\sin2x-\\dfrac{x-1}{2}&gt;0</span>，故该区间没有根.<br><br>在 <span class=\"gk-math\" data-tex=\"[\\dfrac\\pi2,\\dfrac{3\\pi}4]\">[\\dfrac\\pi2,\\dfrac{3\\pi}4]</span> 上，<span class=\"gk-math\" data-tex=\"h&#x27;&#x27;(x)&lt;0\">h&#x27;&#x27;(x)&lt;0</span>，<span class=\"gk-math\" data-tex=\"h&#x27;\">h&#x27;</span> 只变号一次，函数先增后减；又 <span class=\"gk-math\" data-tex=\"h(\\dfrac\\pi2)&lt;0\">h(\\dfrac\\pi2)&lt;0</span>，<span class=\"gk-math\" data-tex=\"h(\\dfrac{3\\pi}4)=\\dfrac32-\\dfrac{3\\pi}{8}&gt;0\">h(\\dfrac{3\\pi}4)=\\dfrac32-\\dfrac{3\\pi}{8}&gt;0</span>，故有且仅有一个根. 最后，因 <span class=\"gk-math\" data-tex=\"3&lt;\\pi&lt;4\">3&lt;\\pi&lt;4</span>，在 <span class=\"gk-math\" data-tex=\"[\\dfrac{3\\pi}4,3]\">[\\dfrac{3\\pi}4,3]</span> 上有 <span class=\"gk-math\" data-tex=\"\\cos2x\\geq0\">\\cos2x\\geq0</span>，从而 <span class=\"gk-math\" data-tex=\"h&#x27;(x)&lt;0\">h&#x27;(x)&lt;0</span>，且 <span class=\"gk-math\" data-tex=\"h(\\dfrac{3\\pi}4)&gt;0\">h(\\dfrac{3\\pi}4)&gt;0</span>，<span class=\"gk-math\" data-tex=\"h(3)=-\\sin6-1&lt;0\">h(3)=-\\sin6-1&lt;0</span>，故有且仅有一个根. 所以交点个数为 <span class=\"gk-math\" data-tex=\"3\">3</span>，故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q11","paperId":"2023-national_paper_a_science","number":11,"type":"single","score":5,"lessonIds":["e1-1.3","6.4","8.6"],"difficulty":"进阶","hint":"以 C 为原点沿 CB、CD 建坐标，由 PC=PD 先确定一个投影分量，再用 ∠PCA=45°。","legacy":false,"legacyReason":"","searchText":"已知四棱锥 P-ABCD 的底面是边长为 4 的正方形， PC=PD=3 ， \\angle PCA=45^\\circ ，则 \\triangle PBC 的面积为（ ） 2\\sqrt{2} 3\\sqrt{2} 4\\sqrt{2} 6\\sqrt{2}","questionHtml":"已知四棱锥 <span class=\"gk-math\" data-tex=\"P-ABCD\">P-ABCD</span> 的底面是边长为 4 的正方形，<span class=\"gk-math\" data-tex=\"PC=PD=3\">PC=PD=3</span>，<span class=\"gk-math\" data-tex=\"\\angle PCA=45^\\circ\">\\angle PCA=45^\\circ</span>，则 <span class=\"gk-math\" data-tex=\"\\triangle PBC\">\\triangle PBC</span> 的面积为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"2\\sqrt{2}\">2\\sqrt{2}</span>","<span class=\"gk-math\" data-tex=\"3\\sqrt{2}\">3\\sqrt{2}</span>","<span class=\"gk-math\" data-tex=\"4\\sqrt{2}\">4\\sqrt{2}</span>","<span class=\"gk-math\" data-tex=\"6\\sqrt{2}\">6\\sqrt{2}</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"建立空间直角坐标系，令 <span class=\"gk-math\" data-tex=\"A=(0,0,0)\">A=(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"B=(4,0,0)\">B=(4,0,0)</span>，<span class=\"gk-math\" data-tex=\"C=(4,4,0)\">C=(4,4,0)</span>，<span class=\"gk-math\" data-tex=\"D=(0,4,0)\">D=(0,4,0)</span>，设 <span class=\"gk-math\" data-tex=\"P=(x,y,z)\">P=(x,y,z)</span>. 由 <span class=\"gk-math\" data-tex=\"PC=PD=3\">PC=PD=3</span> 得 <span class=\"gk-math\" data-tex=\"(x-4)^2+(y-4)^2+z^2=x^2+(y-4)^2+z^2\">(x-4)^2+(y-4)^2+z^2=x^2+(y-4)^2+z^2</span>，所以 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span>. 在三角形 <span class=\"gk-math\" data-tex=\"PCA\">PCA</span> 中，<span class=\"gk-math\" data-tex=\"\\overrightarrow{CP}=(-2,y-4,z)\">\\overrightarrow{CP}=(-2,y-4,z)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{CA}=(-4,-4,0)\">\\overrightarrow{CA}=(-4,-4,0)</span>，故 <span class=\"gk-math\" data-tex=\"\\cos45^\\circ=\\dfrac{\\overrightarrow{CP}\\cdot\\overrightarrow{CA}}{\\lvert CP\\rvert\\lvert CA\\rvert}=\\dfrac{24-4y}{3\\cdot4\\sqrt2}\">\\cos45^\\circ=\\dfrac{\\overrightarrow{CP}\\cdot\\overrightarrow{CA}}{\\lvert CP\\rvert\\lvert CA\\rvert}=\\dfrac{24-4y}{3\\cdot4\\sqrt2}</span>，从而 <span class=\"gk-math\" data-tex=\"y=3\">y=3</span>. 再由 <span class=\"gk-math\" data-tex=\"PC=3\">PC=3</span> 得 <span class=\"gk-math\" data-tex=\"4+1+z^2=9\">4+1+z^2=9</span>，即 <span class=\"gk-math\" data-tex=\"z^2=4\">z^2=4</span>. 因此 <span class=\"gk-math\" data-tex=\"PB^2=(-2)^2+3^2+z^2=17\">PB^2=(-2)^2+3^2+z^2=17</span>，而 <span class=\"gk-math\" data-tex=\"BC=4\">BC=4</span>. 在三角形 <span class=\"gk-math\" data-tex=\"PBC\">PBC</span> 中， <span class=\"gk-math\" data-tex=\"\\cos\\angle PCB=\\dfrac{\\overrightarrow{CP}\\cdot\\overrightarrow{CB}}{\\lvert CP\\rvert\\lvert CB\\rvert}=\\dfrac{4}{3\\cdot4}=\\dfrac13\">\\cos\\angle PCB=\\dfrac{\\overrightarrow{CP}\\cdot\\overrightarrow{CB}}{\\lvert CP\\rvert\\lvert CB\\rvert}=\\dfrac{4}{3\\cdot4}=\\dfrac13</span>，所以 <span class=\"gk-math\" data-tex=\"\\sin\\angle PCB=\\dfrac{2\\sqrt2}{3}\">\\sin\\angle PCB=\\dfrac{2\\sqrt2}{3}</span>. 故 <span class=\"gk-math\" data-tex=\"S_{\\triangle PBC}=\\dfrac12\\cdot PC\\cdot BC\\cdot\\sin\\angle PCB=\\dfrac12\\cdot3\\cdot4\\cdot\\dfrac{2\\sqrt2}{3}=4\\sqrt2\">S_{\\triangle PBC}=\\dfrac12\\cdot PC\\cdot BC\\cdot\\sin\\angle PCB=\\dfrac12\\cdot3\\cdot4\\cdot\\dfrac{2\\sqrt2}{3}=4\\sqrt2</span>，故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q12","paperId":"2023-national_paper_a_science","number":12,"type":"single","score":5,"lessonIds":["e1-3.1","6.4"],"difficulty":"进阶","hint":"设两条焦半径为 u、v，先用 u+v=6 和余弦定理求 uv，再由距离平方和求 OP²。","legacy":false,"legacyReason":"","searchText":"设 O 为坐标原点， F_1 ， F_2 为椭圆 \\frac{x^2}{9}+\\frac{y^2}{6}=1 的两个焦点，点 P 在该椭圆上，且 \\cos\\angle F_1PF_2=\\frac35 . 则 \\lvert OP \\rvert= （ ） \\frac{13}{5} \\frac{\\sqrt{30}}{2} \\frac{14}{5} \\frac{\\sqrt{35}}{2}","questionHtml":"设 <span class=\"gk-math\" data-tex=\"O\">O</span> 为坐标原点，<span class=\"gk-math\" data-tex=\"F_1\">F_1</span>，<span class=\"gk-math\" data-tex=\"F_2\">F_2</span> 为椭圆 <span class=\"gk-math\" data-tex=\"\\frac{x^2}{9}+\\frac{y^2}{6}=1\">\\frac{x^2}{9}+\\frac{y^2}{6}=1</span> 的两个焦点，点 <span class=\"gk-math\" data-tex=\"P\">P</span> 在该椭圆上，且 <span class=\"gk-math\" data-tex=\"\\cos\\angle F_1PF_2=\\frac35\">\\cos\\angle F_1PF_2=\\frac35</span>. 则 <span class=\"gk-math\" data-tex=\"\\lvert OP \\rvert=\">\\lvert OP \\rvert=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\frac{13}{5}\">\\frac{13}{5}</span>","<span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{30}}{2}\">\\frac{\\sqrt{30}}{2}</span>","<span class=\"gk-math\" data-tex=\"\\frac{14}{5}\">\\frac{14}{5}</span>","<span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{35}}{2}\">\\frac{\\sqrt{35}}{2}</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"椭圆的长半轴、短半轴和半焦距分别满足 <span class=\"gk-math\" data-tex=\"a=3\">a=3</span>，<span class=\"gk-math\" data-tex=\"b=\\sqrt6\">b=\\sqrt6</span>，<span class=\"gk-math\" data-tex=\"c=\\sqrt{a^2-b^2}=\\sqrt3\">c=\\sqrt{a^2-b^2}=\\sqrt3</span>，所以 <span class=\"gk-math\" data-tex=\"F_1F_2=2\\sqrt3\">F_1F_2=2\\sqrt3</span>. 设 <span class=\"gk-math\" data-tex=\"PF_1=u\">PF_1=u</span>，<span class=\"gk-math\" data-tex=\"PF_2=v\">PF_2=v</span>，由椭圆定义得 <span class=\"gk-math\" data-tex=\"u+v=2a=6\">u+v=2a=6</span>. 在三角形 <span class=\"gk-math\" data-tex=\"F_1PF_2\">F_1PF_2</span> 中应用余弦定理， <span class=\"gk-math\" data-tex=\"(2\\sqrt3)^2=u^2+v^2-2uv\\cdot\\dfrac35\">(2\\sqrt3)^2=u^2+v^2-2uv\\cdot\\dfrac35</span>. 令 <span class=\"gk-math\" data-tex=\"uv=t\">uv=t</span>，并利用 <span class=\"gk-math\" data-tex=\"u^2+v^2=(u+v)^2-2uv=36-2t\">u^2+v^2=(u+v)^2-2uv=36-2t</span>，得 <span class=\"gk-math\" data-tex=\"12=36-2t-\\dfrac65t\">12=36-2t-\\dfrac65t</span>，所以 <span class=\"gk-math\" data-tex=\"t=\\dfrac{15}{2}\">t=\\dfrac{15}{2}</span>，从而 <span class=\"gk-math\" data-tex=\"u^2+v^2=21\">u^2+v^2=21</span>. 因为 <span class=\"gk-math\" data-tex=\"O\">O</span> 是 <span class=\"gk-math\" data-tex=\"F_1F_2\">F_1F_2</span> 的中点，<span class=\"gk-math\" data-tex=\"OP\">OP</span> 是三角形 <span class=\"gk-math\" data-tex=\"F_1PF_2\">F_1PF_2</span> 的中线，由中线公式 <span class=\"gk-math\" data-tex=\"OP^2=\\dfrac{u^2+v^2}{2}-\\dfrac{F_1F_2^2}{4}=\\dfrac{21}{2}-3=\\dfrac{15}{2}\">OP^2=\\dfrac{u^2+v^2}{2}-\\dfrac{F_1F_2^2}{4}=\\dfrac{21}{2}-3=\\dfrac{15}{2}</span>. 因此 <span class=\"gk-math\" data-tex=\"OP=\\dfrac{\\sqrt{30}}{2}\">OP=\\dfrac{\\sqrt{30}}{2}</span>，故选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q13","paperId":"2023-national_paper_a_science","number":13,"type":"fill","score":5,"lessonIds":["3.2","5.3"],"difficulty":"基础","hint":"把 sin(x+π/2) 写成 cosx，展开平方后让奇次项 (a−2)x 消失。","legacy":false,"legacyReason":"","searchText":"设 f(x)=\\left( x-1 \\right)^2+ax+\\sin\\left( x+\\frac{\\pi}{2} \\right) . 若 f(x) 为偶函数，则 a= ________ . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"f(x)=\\left( x-1 \\right)^2+ax+\\sin\\left( x+\\frac{\\pi}{2} \\right)\">f(x)=\\left( x-1 \\right)^2+ax+\\sin\\left( x+\\frac{\\pi}{2} \\right)</span>. 若 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 为偶函数，则 <span class=\"gk-math\" data-tex=\"a=\">a=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"2","answerKey":"","solutionHtml":"由 <span class=\"gk-math\" data-tex=\"\\sin\\left(x+\\dfrac\\pi2\\right)=\\cos x\">\\sin\\left(x+\\dfrac\\pi2\\right)=\\cos x</span>，得 <span class=\"gk-math\" data-tex=\"f(x)=x^2+(a-2)x+1+\\cos x\">f(x)=x^2+(a-2)x+1+\\cos x</span>. 因此 <span class=\"gk-math\" data-tex=\"f(x)-f(-x)=2(a-2)x\">f(x)-f(-x)=2(a-2)x</span>. 若 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 为偶函数，则对任意 <span class=\"gk-math\" data-tex=\"x\">x</span> 有 <span class=\"gk-math\" data-tex=\"f(x)-f(-x)=0\">f(x)-f(-x)=0</span>，从而 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span>. 代入后 <span class=\"gk-math\" data-tex=\"f(x)=x^2+1+\\cos x\">f(x)=x^2+1+\\cos x</span> 确为偶函数，所以填 <span class=\"gk-math\" data-tex=\"2\">2</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q14","paperId":"2023-national_paper_a_science","number":14,"type":"fill","score":5,"lessonIds":["e1-2.2","2.1"],"difficulty":"进阶","hint":"这是超出当前五册的线性规划题；先求三条边界直线的交点，再比较可行区域顶点的目标值。","legacy":true,"legacyReason":"","searchText":"若 x ， y 满足约束条件 \\begin{cases} 3x-2y\\le 3,\\\\ -2x+3y\\le 3,\\\\ x+y\\ge 1, \\end{cases} 则 z=3x+2y 的最大值为 ________ . ","questionHtml":"若 <span class=\"gk-math\" data-tex=\"x\">x</span>，<span class=\"gk-math\" data-tex=\"y\">y</span> 满足约束条件 <span class=\"gk-math\" data-tex=\"\\begin{cases}\n3x-2y\\le 3,\\\\\n-2x+3y\\le 3,\\\\\nx+y\\ge 1,\n\\end{cases}\">\\begin{cases}\n3x-2y\\le 3,\\\\\n-2x+3y\\le 3,\\\\\nx+y\\ge 1,\n\\end{cases}</span> 则 <span class=\"gk-math\" data-tex=\"z=3x+2y\">z=3x+2y</span> 的最大值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"15","answerKey":"","solutionHtml":"三条边界直线分别为 <span class=\"gk-math\" data-tex=\"3x-2y=3\">3x-2y=3</span>，<span class=\"gk-math\" data-tex=\"-2x+3y=3\">-2x+3y=3</span> 和 <span class=\"gk-math\" data-tex=\"x+y=1\">x+y=1</span>. 它们两两相交得到 <span class=\"gk-math\" data-tex=\"(3,3)\">(3,3)</span>，<span class=\"gk-math\" data-tex=\"(1,0)\">(1,0)</span> 和 <span class=\"gk-math\" data-tex=\"(0,1)\">(0,1)</span>，且这三个点都满足全部约束条件，因此可行域是以它们为顶点的三角形. 目标函数在有界可行域上的最大值必在顶点处取得，而 <span class=\"gk-math\" data-tex=\"3\\cdot3+2\\cdot3=15\">3\\cdot3+2\\cdot3=15</span>，<span class=\"gk-math\" data-tex=\"3\\cdot1+2\\cdot0=3\">3\\cdot1+2\\cdot0=3</span>，<span class=\"gk-math\" data-tex=\"3\\cdot0+2\\cdot1=2\">3\\cdot0+2\\cdot1=2</span>. 所以 <span class=\"gk-math\" data-tex=\"z_{\\max}=15\">z_{\\max}=15</span>，填 <span class=\"gk-math\" data-tex=\"15\">15</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q15","paperId":"2023-national_paper_a_science","number":15,"type":"fill","score":5,"lessonIds":["8.1","e1-2.3"],"difficulty":"进阶","hint":"球心是 EF 中点，给正方体建坐标后，将十二条棱按对称位置分类，检查到球心距离是否跨过半径。","legacy":false,"legacyReason":"","searchText":"在正方体 ABCD-A_1B_1C_1D_1 中， E ， F 分别为 AB ， C_1D_1 的中点，以 EF 为直径的球的球面与该正方体的棱共有 ________ 个公共点. ","questionHtml":"在正方体 <span class=\"gk-math\" data-tex=\"ABCD-A_1B_1C_1D_1\">ABCD-A_1B_1C_1D_1</span> 中，<span class=\"gk-math\" data-tex=\"E\">E</span>，<span class=\"gk-math\" data-tex=\"F\">F</span> 分别为 <span class=\"gk-math\" data-tex=\"AB\">AB</span>，<span class=\"gk-math\" data-tex=\"C_1D_1\">C_1D_1</span> 的中点，以 <span class=\"gk-math\" data-tex=\"EF\">EF</span> 为直径的球的球面与该正方体的棱共有<span class=\"gk-blank\" aria-label=\"填空\">________</span>个公共点.","optionsHtml":[],"answerHtml":"12","answerKey":"","solutionHtml":"设正方体棱长为 <span class=\"gk-math\" data-tex=\"s&gt;0\">s&gt;0</span>，建立坐标系使 <span class=\"gk-math\" data-tex=\"A=(0,0,0)\">A=(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"B=(s,0,0)\">B=(s,0,0)</span>，<span class=\"gk-math\" data-tex=\"C=(s,s,0)\">C=(s,s,0)</span>，<span class=\"gk-math\" data-tex=\"D=(0,s,0)\">D=(0,s,0)</span>，上底面各点的第三坐标为 <span class=\"gk-math\" data-tex=\"s\">s</span>. 则 <span class=\"gk-math\" data-tex=\"E=(\\dfrac{s}{2},0,0)\">E=(\\dfrac{s}{2},0,0)</span>，<span class=\"gk-math\" data-tex=\"F=(\\dfrac{s}{2},s,s)\">F=(\\dfrac{s}{2},s,s)</span>，球心 <span class=\"gk-math\" data-tex=\"O\">O</span> 是 <span class=\"gk-math\" data-tex=\"EF\">EF</span> 的中点，即 <span class=\"gk-math\" data-tex=\"O=(\\dfrac{s}{2},\\dfrac{s}{2},\\dfrac{s}{2})\">O=(\\dfrac{s}{2},\\dfrac{s}{2},\\dfrac{s}{2})</span>，且球半径满足 <span class=\"gk-math\" data-tex=\"R^2=OE^2=\\dfrac{s^2}{2}\">R^2=OE^2=\\dfrac{s^2}{2}</span>.<br><br>对任意一条平行于 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴的棱，其所在直线上两个固定坐标分别为 <span class=\"gk-math\" data-tex=\"0\">0</span> 或 <span class=\"gk-math\" data-tex=\"s\">s</span>，所以球心到该直线的距离平方为 <span class=\"gk-math\" data-tex=\"(\\dfrac{s}{2})^2+(\\dfrac{s}{2})^2=\\dfrac{s^2}{2}=R^2\">(\\dfrac{s}{2})^2+(\\dfrac{s}{2})^2=\\dfrac{s^2}{2}=R^2</span>，且垂足位于棱的中点，故每条这样的棱与球面有且仅有一个公共点. 平行于 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴的 <span class=\"gk-math\" data-tex=\"4\">4</span> 条棱、平行于 <span class=\"gk-math\" data-tex=\"z\">z</span> 轴的 <span class=\"gk-math\" data-tex=\"4\">4</span> 条棱同理. 因而公共点总数为 <span class=\"gk-math\" data-tex=\"4+4+4=12\">4+4+4=12</span>，填 <span class=\"gk-math\" data-tex=\"12\">12</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q16","paperId":"2023-national_paper_a_science","number":16,"type":"fill","score":5,"lessonIds":["6.4","5.5"],"difficulty":"进阶","hint":"先由余弦定理求 AC，再用角平分线性质 BD/DC=AB/AC，配合三角形面积求 AD。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中， \\angle BAC=60^\\circ ， AB=2 ， BC=\\sqrt{6} ， \\angle BAC 的角平分线交 BC 于 D ，则 AD= ________ . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，<span class=\"gk-math\" data-tex=\"\\angle BAC=60^\\circ\">\\angle BAC=60^\\circ</span>，<span class=\"gk-math\" data-tex=\"AB=2\">AB=2</span>，<span class=\"gk-math\" data-tex=\"BC=\\sqrt{6}\">BC=\\sqrt{6}</span>，<span class=\"gk-math\" data-tex=\"\\angle BAC\">\\angle BAC</span> 的角平分线交 <span class=\"gk-math\" data-tex=\"BC\">BC</span> 于 <span class=\"gk-math\" data-tex=\"D\">D</span>，则 <span class=\"gk-math\" data-tex=\"AD=\">AD=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"2","answerKey":"","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"AC=b\">AC=b</span>. 在三角形 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span> 中由余弦定理得 <span class=\"gk-math\" data-tex=\"6=2^2+b^2-2\\cdot2\\cdot b\\cos60^\\circ=b^2-2b+4\">6=2^2+b^2-2\\cdot2\\cdot b\\cos60^\\circ=b^2-2b+4</span>，所以 <span class=\"gk-math\" data-tex=\"b^2-2b-2=0\">b^2-2b-2=0</span>. 因为 <span class=\"gk-math\" data-tex=\"b&gt;0\">b&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"b=1+\\sqrt3\">b=1+\\sqrt3</span>. 设 <span class=\"gk-math\" data-tex=\"AD=d\">AD=d</span>，由角平分线得 <span class=\"gk-math\" data-tex=\"\\angle BAD=\\angle DAC=30^\\circ\">\\angle BAD=\\angle DAC=30^\\circ</span>. 以 <span class=\"gk-math\" data-tex=\"AD\">AD</span> 为公共底边分割三角形面积，有 <span class=\"gk-math\" data-tex=\"\\dfrac12\\cdot AB\\cdot AC\\sin60^\\circ=\\dfrac12\\cdot AD\\cdot AB\\sin30^\\circ+\\dfrac12\\cdot AD\\cdot AC\\sin30^\\circ\">\\dfrac12\\cdot AB\\cdot AC\\sin60^\\circ=\\dfrac12\\cdot AD\\cdot AB\\sin30^\\circ+\\dfrac12\\cdot AD\\cdot AC\\sin30^\\circ</span>，即 <span class=\"gk-math\" data-tex=\"\\dfrac{b\\sqrt3}{2}=\\dfrac{d(2+b)}{4}\">\\dfrac{b\\sqrt3}{2}=\\dfrac{d(2+b)}{4}</span>. 因此 <span class=\"gk-math\" data-tex=\"d=\\dfrac{2b\\sqrt3}{b+2}=\\dfrac{2(1+\\sqrt3)\\sqrt3}{3+\\sqrt3}=2\">d=\\dfrac{2b\\sqrt3}{b+2}=\\dfrac{2(1+\\sqrt3)\\sqrt3}{3+\\sqrt3}=2</span>，填 <span class=\"gk-math\" data-tex=\"2\">2</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q17","paperId":"2023-national_paper_a_science","number":17,"type":"written","score":12,"lessonIds":["e2-4.1","e2-4.3"],"difficulty":"进阶","hint":"先由 n=1 得 a₁=0，再把 n 和 n−1 的关系相减得到相邻项规律；求和时用错位相减。","legacy":false,"legacyReason":"","searchText":"设 S_n 为数列 \\{a_n\\} 的前 n 项和，已知 a_2=1 ， 2S_n=na_n . 求 \\{a_n\\} 的通项公式； 求数列 \\left\\{ \\frac{a_{n+1}}{2^n} \\right\\} 的前 n 项和 T_n . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span> 为数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和，已知 <span class=\"gk-math\" data-tex=\"a_2=1\">a_2=1</span>，<span class=\"gk-math\" data-tex=\"2S_n=na_n\">2S_n=na_n</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的通项公式；</li><li>求数列 <span class=\"gk-math\" data-tex=\"\\left\\{ \\frac{a_{n+1}}{2^n} \\right\\}\">\\left\\{ \\frac{a_{n+1}}{2^n} \\right\\}</span> 的前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和 <span class=\"gk-math\" data-tex=\"T_n\">T_n</span>.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"n=1\">n=1</span> 时，<span class=\"gk-math\" data-tex=\"2S_1=a_1\">2S_1=a_1</span>，即 <span class=\"gk-math\" data-tex=\"2a_1=a_1\">2a_1=a_1</span>，所以 <span class=\"gk-math\" data-tex=\"a_1=0\">a_1=0</span>. 当 <span class=\"gk-math\" data-tex=\"n\\geq2\">n\\geq2</span> 时，分别写出 <span class=\"gk-math\" data-tex=\"2S_n=na_n\">2S_n=na_n</span> 和 <span class=\"gk-math\" data-tex=\"2S_{n-1}=(n-1)a_{n-1}\">2S_{n-1}=(n-1)a_{n-1}</span>，两式相减得 <span class=\"gk-math\" data-tex=\"2a_n=na_n-(n-1)a_{n-1}\">2a_n=na_n-(n-1)a_{n-1}</span>，即 <span class=\"gk-math\" data-tex=\"(n-2)a_n=(n-1)a_{n-1}\">(n-2)a_n=(n-1)a_{n-1}</span>. 对 <span class=\"gk-math\" data-tex=\"n\\geq3\">n\\geq3</span>，有 <span class=\"gk-math\" data-tex=\"\\dfrac{a_n}{n-1}=\\dfrac{a_{n-1}}{n-2}\">\\dfrac{a_n}{n-1}=\\dfrac{a_{n-1}}{n-2}</span>. 由 <span class=\"gk-math\" data-tex=\"a_2=1\">a_2=1</span> 逐步得到 <span class=\"gk-math\" data-tex=\"a_n=n-1\">a_n=n-1</span>（<span class=\"gk-math\" data-tex=\"n\\geq2\">n\\geq2</span>），而 <span class=\"gk-math\" data-tex=\"a_1=0=1-1\">a_1=0=1-1</span>，所以 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的通项公式为 <span class=\"gk-math\" data-tex=\"a_n=n-1\">a_n=n-1</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"a_{k+1}=k\">a_{k+1}=k</span> 得 <span class=\"gk-math\" data-tex=\"T_n=\\displaystyle\\sum_{k=1}^n\\dfrac{k}{2^k}\">T_n=\\displaystyle\\sum_{k=1}^n\\dfrac{k}{2^k}</span>. 注意到 <span class=\"gk-math\" data-tex=\"\\dfrac{k}{2^k}=\\dfrac{k+1}{2^{k-1}}-\\dfrac{k+2}{2^k}\">\\dfrac{k}{2^k}=\\dfrac{k+1}{2^{k-1}}-\\dfrac{k+2}{2^k}</span>，所以 <span class=\"gk-math\" data-tex=\"T_n=2-\\dfrac{n+2}{2^n}=2-(n+2)\\left(\\dfrac12\\right)^n\">T_n=2-\\dfrac{n+2}{2^n}=2-(n+2)\\left(\\dfrac12\\right)^n</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q18","paperId":"2023-national_paper_a_science","number":18,"type":"written","score":12,"lessonIds":["8.6","e1-1.4"],"difficulty":"挑战","hint":"先证明平面 ACC₁A₁ 与 BCC₁B₁ 垂直，把 A₁ 到侧面的距离转化为截面直角三角形里的高。","legacy":false,"legacyReason":"","searchText":"如图，在三棱柱 ABC-A_1B_1C_1 中， A_1C\\perp 底面 ABC ， \\angle ACB=90^\\circ ， AA_1=2 ， A_1 到平面 BCC_1B_1 的距离为 1. 证明 A_1C=AC ； 已知 AA_1 与 BB_1 的距离为 2，求 AB_1 与平面 BCC_1B_1 所成角的正弦值. ","questionHtml":"如图，在三棱柱 <span class=\"gk-math\" data-tex=\"ABC-A_1B_1C_1\">ABC-A_1B_1C_1</span> 中，<span class=\"gk-math\" data-tex=\"A_1C\\perp\">A_1C\\perp</span> 底面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>，<span class=\"gk-math\" data-tex=\"\\angle ACB=90^\\circ\">\\angle ACB=90^\\circ</span>，<span class=\"gk-math\" data-tex=\"AA_1=2\">AA_1=2</span>，<span class=\"gk-math\" data-tex=\"A_1\">A_1</span> 到平面 <span class=\"gk-math\" data-tex=\"BCC_1B_1\">BCC_1B_1</span> 的距离为 1.<br><br><ol class=\"gk-subparts\"><li>证明 <span class=\"gk-math\" data-tex=\"A_1C=AC\">A_1C=AC</span>；</li><li>已知 <span class=\"gk-math\" data-tex=\"AA_1\">AA_1</span> 与 <span class=\"gk-math\" data-tex=\"BB_1\">BB_1</span> 的距离为 2，求 <span class=\"gk-math\" data-tex=\"AB_1\">AB_1</span> 与平面 <span class=\"gk-math\" data-tex=\"BCC_1B_1\">BCC_1B_1</span> 所成角的正弦值.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,401px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2023/national_paper_a_science/q18_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2023/national_paper_a_science/q18_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"385\" height=\"347\" style=\"aspect-ratio:385/347;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>设 <span class=\"gk-math\" data-tex=\"AC=p\">AC=p</span>，<span class=\"gk-math\" data-tex=\"BC=q\">BC=q</span>，<span class=\"gk-math\" data-tex=\"A_1C=r\">A_1C=r</span>. 建立空间直角坐标系，取 <span class=\"gk-math\" data-tex=\"C=(0,0,0)\">C=(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"A=(p,0,0)\">A=(p,0,0)</span>，<span class=\"gk-math\" data-tex=\"B=(0,q,0)\">B=(0,q,0)</span>，<span class=\"gk-math\" data-tex=\"A_1=(0,0,r)\">A_1=(0,0,r)</span>. 由于三棱柱的侧棱平行且等长，平移向量为 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AA_1}=(-p,0,r)\">\\overrightarrow{AA_1}=(-p,0,r)</span>，故 <span class=\"gk-math\" data-tex=\"C_1=(-p,0,r)\">C_1=(-p,0,r)</span>，<span class=\"gk-math\" data-tex=\"B_1=(-p,q,r)\">B_1=(-p,q,r)</span>. 平面 <span class=\"gk-math\" data-tex=\"BCC_1B_1\">BCC_1B_1</span> 的一个法向量为 <span class=\"gk-math\" data-tex=\"\\bs n=(r,0,p)\">\\bs n=(r,0,p)</span>，其方程为 <span class=\"gk-math\" data-tex=\"rx+pz=0\">rx+pz=0</span>. 又 <span class=\"gk-math\" data-tex=\"AA_1=2\">AA_1=2</span>，所以 <span class=\"gk-math\" data-tex=\"p^2+r^2=4\">p^2+r^2=4</span>. 由点到平面的距离公式， <span class=\"gk-math\" data-tex=\"1=\\dfrac{pr}{\\sqrt{p^2+r^2}}=\\dfrac{pr}{2}\">1=\\dfrac{pr}{\\sqrt{p^2+r^2}}=\\dfrac{pr}{2}</span>，故 <span class=\"gk-math\" data-tex=\"pr=2\">pr=2</span>. 因为 <span class=\"gk-math\" data-tex=\"p^2+r^2\\geq2pr\">p^2+r^2\\geq2pr</span>，且 <span class=\"gk-math\" data-tex=\"p^2+r^2=2pr=4\">p^2+r^2=2pr=4</span>，所以 <span class=\"gk-math\" data-tex=\"p=r=\\sqrt2\">p=r=\\sqrt2</span>，即 <span class=\"gk-math\" data-tex=\"A_1C=AC\">A_1C=AC</span>.</li><li>令 <span class=\"gk-math\" data-tex=\"\\bs v=(-p,0,r)\">\\bs v=(-p,0,r)</span> 为直线 <span class=\"gk-math\" data-tex=\"AA_1\">AA_1</span> 和 <span class=\"gk-math\" data-tex=\"BB_1\">BB_1</span> 的方向向量，令 <span class=\"gk-math\" data-tex=\"\\bs w=\\overrightarrow{AB}=(-p,q,0)\">\\bs w=\\overrightarrow{AB}=(-p,q,0)</span>. 两条平行直线间的距离满足 <div class=\"gk-math display\" data-tex=\"2^2=\\lvert\\bs w\\rvert^2-\\frac{(\\bs w\\cdot\\bs v)^2}{\\lvert\\bs v\\rvert^2}\n=p^2+q^2-\\frac{p^4}{4}=q^2+1\">2^2=\\lvert\\bs w\\rvert^2-\\frac{(\\bs w\\cdot\\bs v)^2}{\\lvert\\bs v\\rvert^2}\n=p^2+q^2-\\frac{p^4}{4}=q^2+1</div> 所以 <span class=\"gk-math\" data-tex=\"q^2=3\">q^2=3</span>. 于是 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AB_1}=(-2p,q,r)\">\\overrightarrow{AB_1}=(-2p,q,r)</span>，<span class=\"gk-math\" data-tex=\"\\lvert AB_1\\rvert^2=4p^2+q^2+r^2=13\">\\lvert AB_1\\rvert^2=4p^2+q^2+r^2=13</span>. 取平面 <span class=\"gk-math\" data-tex=\"BCC_1B_1\">BCC_1B_1</span> 的法向量 <span class=\"gk-math\" data-tex=\"\\bs n=(r,0,p)\">\\bs n=(r,0,p)</span>，则 <span class=\"gk-math\" data-tex=\"\\lvert\\overrightarrow{AB_1}\\cdot\\bs n\\rvert=\\lvert-2pr+pr\\rvert=2\">\\lvert\\overrightarrow{AB_1}\\cdot\\bs n\\rvert=\\lvert-2pr+pr\\rvert=2</span>，且 <span class=\"gk-math\" data-tex=\"\\lvert\\bs n\\rvert=2\">\\lvert\\bs n\\rvert=2</span>. 因此 <span class=\"gk-math\" data-tex=\"AB_1\">AB_1</span> 与该平面所成角的正弦值为 <span class=\"gk-math\" data-tex=\"\\dfrac{\\lvert\\overrightarrow{AB_1}\\cdot\\bs n\\rvert}{\\lvert AB_1\\rvert\\lvert\\bs n\\rvert}=\\dfrac{2}{\\sqrt{13}\\cdot2}=\\dfrac{\\sqrt{13}}{13}\">\\dfrac{\\lvert\\overrightarrow{AB_1}\\cdot\\bs n\\rvert}{\\lvert AB_1\\rvert\\lvert\\bs n\\rvert}=\\dfrac{2}{\\sqrt{13}\\cdot2}=\\dfrac{\\sqrt{13}}{13}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q19","paperId":"2023-national_paper_a_science","number":19,"type":"written","score":12,"lessonIds":["e3-7.4","e3-7.3","e3-8.3"],"difficulty":"进阶","hint":"X 可取 0、1、2，先按从四十只中选二十只的组合数计算分布，再合并两组数据找中位数。","legacy":false,"legacyReason":"","searchText":"一项试验旨在研究臭氧效应. 试验方案如下：选 40 只小白鼠，随机地将其中 20 只分配到试验组，另外 20 只分配到对照组，试验组的小白鼠饲养在高浓度臭氧环境，对照组的小白鼠饲养在正常环境，一段时间后统计每只小白鼠体重的增加量（单位： g ）. 设 X 表示指定的两只小白鼠中分配到对照组的只数，求 X 的分布列和数学期望； 试验结果如下： 对照组的小白鼠体重的增加量从小到大排序为： 15.2， 18.8， 20.2， 21.3， 22.5， 23.2， 25.8， 26.5， 27.5， 30.1， 32.6， 34.3， 34.8， 35.6， 35.6， 35.8， 36.2， 37.3， 40.5， 43.2 试验组的小白鼠体重的增加量从小到大排序为： 7.8， 9.2， 11.4， 12.4， 13.2， 15.5， 16.5， 18.0， 18.8， 19.2， 19.8， 20.2， 21.6， 22.8， 23.6， 23.9， 25.1， 28.2， 32.3， 36.5 求 40 只小鼠体重的增加量的中位数 m ，再分别统计两样本中小于 m 与不小于 m 的数据的个数，完成如下列联表； <m \\ge m 对照组 试验组 根据（1）中的列联表，能否有 95% 的把握认为小白鼠在高浓度臭氧环境中与在正常环境中体重的增加量有差异？ 附： K^2=\\dfrac{n\\left( ad-bc \\right)^2}{\\left( a+b \\right)\\left( c+d \\right)\\left( a+c \\right)\\left( b+d \\right)} ， P\\left( K^2\\ge k \\right) 0.100 0.050 0.010 k 2.706 3.841 6.635 ","questionHtml":"一项试验旨在研究臭氧效应. 试验方案如下：选 40 只小白鼠，随机地将其中 20 只分配到试验组，另外 20 只分配到对照组，试验组的小白鼠饲养在高浓度臭氧环境，对照组的小白鼠饲养在正常环境，一段时间后统计每只小白鼠体重的增加量（单位：<span class=\"gk-math\" data-tex=\"g\">g</span>）.<br><br><ol class=\"gk-subparts\"><li>设 <span class=\"gk-math\" data-tex=\"X\">X</span> 表示指定的两只小白鼠中分配到对照组的只数，求 <span class=\"gk-math\" data-tex=\"X\">X</span> 的分布列和数学期望；</li><li>试验结果如下：<br><br>对照组的小白鼠体重的增加量从小到大排序为：<br><br>15.2， 18.8， 20.2， 21.3， 22.5， 23.2， 25.8， 26.5， 27.5， 30.1，<br><br>32.6， 34.3， 34.8， 35.6， 35.6， 35.8， 36.2， 37.3， 40.5， 43.2<br><br>试验组的小白鼠体重的增加量从小到大排序为：<br><br>7.8， 9.2， 11.4， 12.4， 13.2， 15.5， 16.5， 18.0， 18.8， 19.2，<br><br>19.8， 20.2， 21.6， 22.8， 23.6， 23.9， 25.1， 28.2， 32.3， 36.5<br><br><ol class=\"gk-subparts\"><li>求 40 只小鼠体重的增加量的中位数 <span class=\"gk-math\" data-tex=\"m\">m</span>，再分别统计两样本中小于 <span class=\"gk-math\" data-tex=\"m\">m</span> 与不小于 <span class=\"gk-math\" data-tex=\"m\">m</span> 的数据的个数，完成如下列联表；<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td></td><td><span class=\"gk-math\" data-tex=\"&lt;m\">&lt;m</span></td><td><span class=\"gk-math\" data-tex=\"\\ge m\">\\ge m</span></td></tr><tr><td><span>对照组</span></td><td></td><td></td></tr><tr><td><span>试验组</span></td><td></td><td></td></tr></table></div></div></li><li>根据（1）中的列联表，能否有 95% 的把握认为小白鼠在高浓度臭氧环境中与在正常环境中体重的增加量有差异？</li></ol></li></ol><br><br>附：<span class=\"gk-math\" data-tex=\"K^2=\\dfrac{n\\left( ad-bc \\right)^2}{\\left( a+b \\right)\\left( c+d \\right)\\left( a+c \\right)\\left( b+d \\right)}\">K^2=\\dfrac{n\\left( ad-bc \\right)^2}{\\left( a+b \\right)\\left( c+d \\right)\\left( a+c \\right)\\left( b+d \\right)}</span>，<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td><span class=\"gk-math\" data-tex=\"P\\left( K^2\\ge k \\right)\">P\\left( K^2\\ge k \\right)</span></td><td>0.100</td><td>0.050</td><td>0.010</td></tr><tr><td><span class=\"gk-math\" data-tex=\"k\">k</span></td><td>2.706</td><td>3.841</td><td>6.635</td></tr></table></div></div>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>指定的两只小白鼠中分配到对照组的只数 <span class=\"gk-math\" data-tex=\"X\">X</span> 可能取 <span class=\"gk-math\" data-tex=\"0\">0</span>，<span class=\"gk-math\" data-tex=\"1\">1</span>，<span class=\"gk-math\" data-tex=\"2\">2</span>. 从 <span class=\"gk-math\" data-tex=\"40\">40</span> 只小白鼠中任选两只共有 <span class=\"gk-math\" data-tex=\"\\mathrm C_{40}^{2}\">\\mathrm C_{40}^{2}</span> 种选法，因此 <span class=\"gk-math\" data-tex=\"P(X=0)=\\dfrac{\\mathrm C_{20}^{0}\\mathrm C_{20}^{2}}{\\mathrm C_{40}^{2}}=\\dfrac{19}{78}\">P(X=0)=\\dfrac{\\mathrm C_{20}^{0}\\mathrm C_{20}^{2}}{\\mathrm C_{40}^{2}}=\\dfrac{19}{78}</span>， <span class=\"gk-math\" data-tex=\"P(X=1)=\\dfrac{\\mathrm C_{20}^{1}\\mathrm C_{20}^{1}}{\\mathrm C_{40}^{2}}=\\dfrac{20}{39}\">P(X=1)=\\dfrac{\\mathrm C_{20}^{1}\\mathrm C_{20}^{1}}{\\mathrm C_{40}^{2}}=\\dfrac{20}{39}</span>， <span class=\"gk-math\" data-tex=\"P(X=2)=\\dfrac{\\mathrm C_{20}^{2}\\mathrm C_{20}^{0}}{\\mathrm C_{40}^{2}}=\\dfrac{19}{78}\">P(X=2)=\\dfrac{\\mathrm C_{20}^{2}\\mathrm C_{20}^{0}}{\\mathrm C_{40}^{2}}=\\dfrac{19}{78}</span>. 所以分布列为<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td><span class=\"gk-math\" data-tex=\"X\">X</span></td><td>0</td><td>1</td><td>2</td></tr><tr><td><span class=\"gk-math\" data-tex=\"P(X)\">P(X)</span></td><td><span class=\"gk-math\" data-tex=\"\\dfrac{19}{78}\">\\dfrac{19}{78}</span></td><td><span class=\"gk-math\" data-tex=\"\\dfrac{20}{39}\">\\dfrac{20}{39}</span></td><td><span class=\"gk-math\" data-tex=\"\\dfrac{19}{78}\">\\dfrac{19}{78}</span></td></tr></table></div></div><br><br><span class=\"gk-math\" data-tex=\"\\displaystyle E(X)=0\\cdot\\dfrac{19}{78}+1\\cdot\\dfrac{20}{39}+2\\cdot\\dfrac{19}{78}=1\">\\displaystyle E(X)=0\\cdot\\dfrac{19}{78}+1\\cdot\\dfrac{20}{39}+2\\cdot\\dfrac{19}{78}=1</span>.</li><li><ol class=\"gk-subparts\"><li>将两组数据合并并按从小到大排序后，第 <span class=\"gk-math\" data-tex=\"20\">20</span> 个和第 <span class=\"gk-math\" data-tex=\"21\">21</span> 个数据分别为 <span class=\"gk-math\" data-tex=\"23.2\">23.2</span> 和 <span class=\"gk-math\" data-tex=\"23.6\">23.6</span>，所以中位数 <span class=\"gk-math\" data-tex=\"m=\\dfrac{23.2+23.6}{2}=23.4\">m=\\dfrac{23.2+23.6}{2}=23.4</span>. 对照组中小于 <span class=\"gk-math\" data-tex=\"m\">m</span> 的数据有 <span class=\"gk-math\" data-tex=\"6\">6</span> 个，试验组中小于 <span class=\"gk-math\" data-tex=\"m\">m</span> 的数据有 <span class=\"gk-math\" data-tex=\"14\">14</span> 个，因此列联表为<br><br><div class=\"gk-center\"><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td></td><td><span class=\"gk-math\" data-tex=\"&lt;m\">&lt;m</span></td><td><span class=\"gk-math\" data-tex=\"\\ge m\">\\ge m</span></td><td>合计</td></tr><tr><td>对照组</td><td>6</td><td>14</td><td>20</td></tr><tr><td>试验组</td><td>14</td><td>6</td><td>20</td></tr><tr><td>合计</td><td>20</td><td>20</td><td>40</td></tr></table></div></div></li><li>取 <span class=\"gk-math\" data-tex=\"a=6\">a=6</span>，<span class=\"gk-math\" data-tex=\"b=14\">b=14</span>，<span class=\"gk-math\" data-tex=\"c=14\">c=14</span>，<span class=\"gk-math\" data-tex=\"d=6\">d=6</span>，<span class=\"gk-math\" data-tex=\"n=40\">n=40</span>，则 <div class=\"gk-math display\" data-tex=\"K^2=\\frac{40(6\\cdot6-14\\cdot14)^2}{20\\cdot20\\cdot20\\cdot20}=6.4&gt;3.841\">K^2=\\frac{40(6\\cdot6-14\\cdot14)^2}{20\\cdot20\\cdot20\\cdot20}=6.4&gt;3.841</div> 由题给数据可知，在显著性水平 <span class=\"gk-math\" data-tex=\"0.05\">0.05</span> 下有 <span class=\"gk-math\" data-tex=\"95\\%\">95\\%</span> 的把握认为小白鼠在高浓度臭氧环境中与在正常环境中体重的增加量有差异.</li></ol></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q20","paperId":"2023-national_paper_a_science","number":20,"type":"written","score":12,"lessonIds":["e1-3.3","e1-2.2","2.2"],"difficulty":"挑战","hint":"先由 x=2y−1 联立抛物线，利用弦长与两根差求 p；面积最值再用两条垂直焦半径。","legacy":false,"legacyReason":"","searchText":"已知直线 x-2y+1=0 与抛物线 C:y^2=2px （ p>0 ）交于 A ， B 两点，且 \\lvert AB \\rvert=4\\sqrt{15} . 求 p ； 设 F 为 C 的焦点， M ， N 为 C 上两点， \\overrightarrow{FM}\\cdot\\overrightarrow{FN}=0 ，求 \\triangle MFN 面积的最小值. ","questionHtml":"已知直线 <span class=\"gk-math\" data-tex=\"x-2y+1=0\">x-2y+1=0</span> 与抛物线 <span class=\"gk-math\" data-tex=\"C:y^2=2px\">C:y^2=2px</span>（<span class=\"gk-math\" data-tex=\"p&gt;0\">p&gt;0</span>）交于 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 两点，且 <span class=\"gk-math\" data-tex=\"\\lvert AB \\rvert=4\\sqrt{15}\">\\lvert AB \\rvert=4\\sqrt{15}</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"p\">p</span>；</li><li>设 <span class=\"gk-math\" data-tex=\"F\">F</span> 为 <span class=\"gk-math\" data-tex=\"C\">C</span> 的焦点，<span class=\"gk-math\" data-tex=\"M\">M</span>，<span class=\"gk-math\" data-tex=\"N\">N</span> 为 <span class=\"gk-math\" data-tex=\"C\">C</span> 上两点，<span class=\"gk-math\" data-tex=\"\\overrightarrow{FM}\\cdot\\overrightarrow{FN}=0\">\\overrightarrow{FM}\\cdot\\overrightarrow{FN}=0</span>，求 <span class=\"gk-math\" data-tex=\"\\triangle MFN\">\\triangle MFN</span> 面积的最小值.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>设直线与抛物线的两个交点的纵坐标分别为 <span class=\"gk-math\" data-tex=\"y_1\">y_1</span>，<span class=\"gk-math\" data-tex=\"y_2\">y_2</span>. 由直线方程得 <span class=\"gk-math\" data-tex=\"x=2y-1\">x=2y-1</span>，代入 <span class=\"gk-math\" data-tex=\"y^2=2px\">y^2=2px</span> 得 <span class=\"gk-math\" data-tex=\"y^2-4py+2p=0\">y^2-4py+2p=0</span>，所以 <span class=\"gk-math\" data-tex=\"y_1+y_2=4p\">y_1+y_2=4p</span>，<span class=\"gk-math\" data-tex=\"y_1y_2=2p\">y_1y_2=2p</span>. 又 <div class=\"gk-math display\" data-tex=\"\\lvert AB\\rvert^2=(x_1-x_2)^2+(y_1-y_2)^2=5(y_1-y_2)^2\">\\lvert AB\\rvert^2=(x_1-x_2)^2+(y_1-y_2)^2=5(y_1-y_2)^2</div> 且 <span class=\"gk-math\" data-tex=\"(y_1-y_2)^2=(y_1+y_2)^2-4y_1y_2=16p^2-8p\">(y_1-y_2)^2=(y_1+y_2)^2-4y_1y_2=16p^2-8p</span>. 由 <span class=\"gk-math\" data-tex=\"\\lvert AB\\rvert=4\\sqrt{15}\">\\lvert AB\\rvert=4\\sqrt{15}</span> 得 <span class=\"gk-math\" data-tex=\"5(16p^2-8p)=240\">5(16p^2-8p)=240</span>，即 <span class=\"gk-math\" data-tex=\"2p^2-p-6=0\">2p^2-p-6=0</span>. 因为 <span class=\"gk-math\" data-tex=\"p&gt;0\">p&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"p=2\">p=2</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"p=2\">p=2</span> 得抛物线方程为 <span class=\"gk-math\" data-tex=\"y^2=4x\">y^2=4x</span>，其焦点为 <span class=\"gk-math\" data-tex=\"F=(1,0)\">F=(1,0)</span>. 设直线 <span class=\"gk-math\" data-tex=\"MN\">MN</span> 的方程为 <span class=\"gk-math\" data-tex=\"x=ry+s\">x=ry+s</span>，其中 <span class=\"gk-math\" data-tex=\"M=(x_1,y_1)\">M=(x_1,y_1)</span>，<span class=\"gk-math\" data-tex=\"N=(x_2,y_2)\">N=(x_2,y_2)</span>. 交点纵坐标满足 <span class=\"gk-math\" data-tex=\"y^2-4ry-4s=0\">y^2-4ry-4s=0</span>，所以 <span class=\"gk-math\" data-tex=\"y_1+y_2=4r\">y_1+y_2=4r</span>，<span class=\"gk-math\" data-tex=\"y_1y_2=-4s\">y_1y_2=-4s</span>. 由 <span class=\"gk-math\" data-tex=\"\\overrightarrow{FM}\\cdot\\overrightarrow{FN}=0\">\\overrightarrow{FM}\\cdot\\overrightarrow{FN}=0</span> 得 <div class=\"gk-math display\" data-tex=\"(ry_1+s-1)(ry_2+s-1)+y_1y_2=0\">(ry_1+s-1)(ry_2+s-1)+y_1y_2=0</div> 代入根与系数的关系并化简，得 <span class=\"gk-math\" data-tex=\"(s-1)^2=4(s+r^2)\">(s-1)^2=4(s+r^2)</span>，即 <span class=\"gk-math\" data-tex=\"r^2=\\dfrac{s^2-6s+1}{4}\">r^2=\\dfrac{s^2-6s+1}{4}</span>. 因为 <span class=\"gk-math\" data-tex=\"r^2\\geq0\">r^2\\geq0</span>，所以 <span class=\"gk-math\" data-tex=\"s\\leq3-2\\sqrt2\">s\\leq3-2\\sqrt2</span> 或 <span class=\"gk-math\" data-tex=\"s\\geq3+2\\sqrt2\">s\\geq3+2\\sqrt2</span>.<br><br>由根的差的平方，<span class=\"gk-math\" data-tex=\"\\lvert y_1-y_2\\rvert=4\\sqrt{r^2+s}\">\\lvert y_1-y_2\\rvert=4\\sqrt{r^2+s}</span>，而直线 <span class=\"gk-math\" data-tex=\"MN\">MN</span> 到焦点 <span class=\"gk-math\" data-tex=\"F\">F</span> 的距离为 <span class=\"gk-math\" data-tex=\"d=\\dfrac{\\lvert1-s\\rvert}{\\sqrt{1+r^2}}\">d=\\dfrac{\\lvert1-s\\rvert}{\\sqrt{1+r^2}}</span>，故 <div class=\"gk-math display\" data-tex=\"\\lvert MN\\rvert=4\\sqrt{r^2+s}\\sqrt{1+r^2}\">\\lvert MN\\rvert=4\\sqrt{r^2+s}\\sqrt{1+r^2}</div> <div class=\"gk-math display\" data-tex=\"S_{\\triangle MFN}=\\dfrac12\\lvert MN\\rvert d\n=2\\lvert1-s\\rvert\\sqrt{r^2+s}\n=(s-1)^2\">S_{\\triangle MFN}=\\dfrac12\\lvert MN\\rvert d\n=2\\lvert1-s\\rvert\\sqrt{r^2+s}\n=(s-1)^2</div> 当 <span class=\"gk-math\" data-tex=\"s\\leq3-2\\sqrt2\">s\\leq3-2\\sqrt2</span> 时，<span class=\"gk-math\" data-tex=\"(s-1)^2\">(s-1)^2</span> 的最小值在 <span class=\"gk-math\" data-tex=\"s=3-2\\sqrt2\">s=3-2\\sqrt2</span> 处取得；当 <span class=\"gk-math\" data-tex=\"s\\geq3+2\\sqrt2\">s\\geq3+2\\sqrt2</span> 时所得最小值为 <span class=\"gk-math\" data-tex=\"12+8\\sqrt2\">12+8\\sqrt2</span>. 因此 <span class=\"gk-math\" data-tex=\"S_{\\min}=(3-2\\sqrt2-1)^2=12-8\\sqrt2\">S_{\\min}=(3-2\\sqrt2-1)^2=12-8\\sqrt2</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q21","paperId":"2023-national_paper_a_science","number":21,"type":"written","score":12,"lessonIds":["e2-5.3","5.5"],"difficulty":"挑战","hint":"先对 sinx/cos³x 求导，把结果用 tan²x 表示，便于判断导数符号和恒成立条件。","legacy":false,"legacyReason":"","searchText":"已知函数 f(x)=ax-\\frac{\\sin x}{\\cos^3x} ， x\\in\\left( 0,\\frac{\\pi}{2} \\right) . 当 a=8 时，讨论 f(x) 的单调性； 若 f(x)<\\sin2x 恒成立，求 a 的取值范围. ","questionHtml":"已知函数 <span class=\"gk-math\" data-tex=\"f(x)=ax-\\frac{\\sin x}{\\cos^3x}\">f(x)=ax-\\frac{\\sin x}{\\cos^3x}</span>，<span class=\"gk-math\" data-tex=\"x\\in\\left( 0,\\frac{\\pi}{2} \\right)\">x\\in\\left( 0,\\frac{\\pi}{2} \\right)</span>.<br><br><ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"a=8\">a=8</span> 时，讨论 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的单调性；</li><li>若 <span class=\"gk-math\" data-tex=\"f(x)&lt;\\sin2x\">f(x)&lt;\\sin2x</span> 恒成立，求 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>令 <span class=\"gk-math\" data-tex=\"t=\\cos^2x\">t=\\cos^2x</span>，则 <span class=\"gk-math\" data-tex=\"t\\in(0,1)\">t\\in(0,1)</span>，且 <div class=\"gk-math display\" data-tex=\"f&#x27;(x)=a-\\frac{\\cos^2x+3\\sin^2x}{\\cos^4x}\n=a-\\frac{3-2t}{t^2}\">f&#x27;(x)=a-\\frac{\\cos^2x+3\\sin^2x}{\\cos^4x}\n=a-\\frac{3-2t}{t^2}</div> 当 <span class=\"gk-math\" data-tex=\"a=8\">a=8</span> 时， <span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\dfrac{8t^2+2t-3}{t^2}=\\dfrac{(2t-1)(4t+3)}{t^2}\">f&#x27;(x)=\\dfrac{8t^2+2t-3}{t^2}=\\dfrac{(2t-1)(4t+3)}{t^2}</span>. 因为 <span class=\"gk-math\" data-tex=\"4t+3&gt;0\">4t+3&gt;0</span>，所以当 <span class=\"gk-math\" data-tex=\"t&gt;\\dfrac12\">t&gt;\\dfrac12</span>，即 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;\\dfrac\\pi4\">0&lt;x&lt;\\dfrac\\pi4</span> 时，<span class=\"gk-math\" data-tex=\"f&#x27;(x)&gt;0\">f&#x27;(x)&gt;0</span>；当 <span class=\"gk-math\" data-tex=\"t&lt;\\dfrac12\">t&lt;\\dfrac12</span>，即 <span class=\"gk-math\" data-tex=\"\\dfrac\\pi4&lt;x&lt;\\dfrac\\pi2\">\\dfrac\\pi4&lt;x&lt;\\dfrac\\pi2</span> 时，<span class=\"gk-math\" data-tex=\"f&#x27;(x)&lt;0\">f&#x27;(x)&lt;0</span>. 因此 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在 <span class=\"gk-math\" data-tex=\"\\left(0,\\dfrac\\pi4\\right)\">\\left(0,\\dfrac\\pi4\\right)</span> 上单调递增，在 <span class=\"gk-math\" data-tex=\"\\left(\\dfrac\\pi4,\\dfrac\\pi2\\right)\">\\left(\\dfrac\\pi4,\\dfrac\\pi2\\right)</span> 上单调递减.</li><li>令 <span class=\"gk-math\" data-tex=\"g_a(x)=f(x)-\\sin2x\">g_a(x)=f(x)-\\sin2x</span>. 则 <span class=\"gk-math\" data-tex=\"g_a&#x27;(x)=a-\\frac{3-2t}{t^2}-2(2t-1)\">g_a&#x27;(x)=a-\\frac{3-2t}{t^2}-2(2t-1)</span>，<span class=\"gk-math\" data-tex=\"t=\\cos^2x\">t=\\cos^2x</span>. 特别地，当 <span class=\"gk-math\" data-tex=\"a=3\">a=3</span> 时， <div class=\"gk-math display\" data-tex=\"g_3&#x27;(x)=5+\\frac2t-\\frac3{t^2}-4t\n=-\\frac{(1-t)^2(4t+3)}{t^2}&lt;0\">g_3&#x27;(x)=5+\\frac2t-\\frac3{t^2}-4t\n=-\\frac{(1-t)^2(4t+3)}{t^2}&lt;0</div> 又 <span class=\"gk-math\" data-tex=\"\\displaystyle\\lim_{x\\to0+}g_3(x)=0\">\\displaystyle\\lim_{x\\to0+}g_3(x)=0</span>，所以对任意 <span class=\"gk-math\" data-tex=\"x\\in\\left(0,\\dfrac\\pi2\\right)\">x\\in\\left(0,\\dfrac\\pi2\\right)</span>，都有 <span class=\"gk-math\" data-tex=\"g_3(x)&lt;0\">g_3(x)&lt;0</span>. 当 <span class=\"gk-math\" data-tex=\"a\\leq3\">a\\leq3</span> 时， <span class=\"gk-math\" data-tex=\"g_a(x)=g_3(x)+(a-3)x&lt;0\">g_a(x)=g_3(x)+(a-3)x&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"a\\leq3\">a\\leq3</span> 时恒有 <span class=\"gk-math\" data-tex=\"f(x)&lt;\\sin2x\">f(x)&lt;\\sin2x</span>. 当 <span class=\"gk-math\" data-tex=\"a&gt;3\">a&gt;3</span> 时， <div class=\"gk-math display\" data-tex=\"\\lim_{x\\to0+}\\frac{g_a(x)}{x}\n=a-\\lim_{x\\to0+}\\frac{\\sin x}{x\\cos^3x}-\\lim_{x\\to0+}\\frac{\\sin2x}{x}\n=a-3&gt;0\">\\lim_{x\\to0+}\\frac{g_a(x)}{x}\n=a-\\lim_{x\\to0+}\\frac{\\sin x}{x\\cos^3x}-\\lim_{x\\to0+}\\frac{\\sin2x}{x}\n=a-3&gt;0</div> 于是 <span class=\"gk-math\" data-tex=\"x\">x</span> 充分接近 <span class=\"gk-math\" data-tex=\"0\">0</span> 时 <span class=\"gk-math\" data-tex=\"g_a(x)&gt;0\">g_a(x)&gt;0</span>，不满足题意. 所以 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围为 <span class=\"gk-math\" data-tex=\"(-\\infty,3]\">(-\\infty,3]</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q22","paperId":"2023-national_paper_a_science","number":22,"type":"written","score":10,"lessonIds":["e1-2.1","e1-2.2"],"difficulty":"进阶","hint":"这是超出当前五册的参数方程与极坐标题；先分别令 y=0、x=0 求两交点对应的参数，再用距离乘积条件。","legacy":true,"legacyReason":"","searchText":"已知点 P(2,1) ，直线 l 的参数方程为 x=2+t\\cos\\alpha ， y=1+t\\sin\\alpha （ t 为参数）， \\alpha 为 l 的倾斜角， l 与 x 轴正半轴， y 轴正半轴分别交于 A ， B 两点，且 \\lvert PA \\rvert\\cdot\\lvert PB \\rvert=4 . 求 \\alpha ； 以坐标原点为极点， x 轴正半轴为极轴建立极坐标系，求 l 的极坐标方程. ","questionHtml":"已知点 <span class=\"gk-math\" data-tex=\"P(2,1)\">P(2,1)</span>，直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 的参数方程为 <span class=\"gk-math\" data-tex=\"x=2+t\\cos\\alpha\">x=2+t\\cos\\alpha</span>，<span class=\"gk-math\" data-tex=\"y=1+t\\sin\\alpha\">y=1+t\\sin\\alpha</span>（<span class=\"gk-math\" data-tex=\"t\">t</span> 为参数），<span class=\"gk-math\" data-tex=\"\\alpha\">\\alpha</span> 为 <span class=\"gk-math\" data-tex=\"l\">l</span> 的倾斜角，<span class=\"gk-math\" data-tex=\"l\">l</span> 与 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴正半轴，<span class=\"gk-math\" data-tex=\"y\">y</span> 轴正半轴分别交于 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span> 两点，且 <span class=\"gk-math\" data-tex=\"\\lvert PA \\rvert\\cdot\\lvert PB \\rvert=4\">\\lvert PA \\rvert\\cdot\\lvert PB \\rvert=4</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"\\alpha\">\\alpha</span>；</li><li>以坐标原点为极点，<span class=\"gk-math\" data-tex=\"x\">x</span> 轴正半轴为极轴建立极坐标系，求 <span class=\"gk-math\" data-tex=\"l\">l</span> 的极坐标方程.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>因为直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 分别与 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴、<span class=\"gk-math\" data-tex=\"y\">y</span> 轴正半轴相交，所以 <span class=\"gk-math\" data-tex=\"\\dfrac\\pi2&lt;\\alpha&lt;\\pi\">\\dfrac\\pi2&lt;\\alpha&lt;\\pi</span>，从而 <span class=\"gk-math\" data-tex=\"\\sin\\alpha&gt;0\">\\sin\\alpha&gt;0</span>，<span class=\"gk-math\" data-tex=\"\\cos\\alpha&lt;0\">\\cos\\alpha&lt;0</span>. 令参数方程中的 <span class=\"gk-math\" data-tex=\"y=0\">y=0</span>，得 <span class=\"gk-math\" data-tex=\"t_A=-\\dfrac1{\\sin\\alpha}\">t_A=-\\dfrac1{\\sin\\alpha}</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert PA\\rvert=\\dfrac1{\\sin\\alpha}\">\\lvert PA\\rvert=\\dfrac1{\\sin\\alpha}</span>. 令 <span class=\"gk-math\" data-tex=\"x=0\">x=0</span>，得 <span class=\"gk-math\" data-tex=\"t_B=-\\dfrac2{\\cos\\alpha}\">t_B=-\\dfrac2{\\cos\\alpha}</span>，所以 <span class=\"gk-math\" data-tex=\"\\lvert PB\\rvert=-\\dfrac2{\\cos\\alpha}\">\\lvert PB\\rvert=-\\dfrac2{\\cos\\alpha}</span>. 由题意 <div class=\"gk-math display\" data-tex=\"\\lvert PA\\rvert\\lvert PB\\rvert\n=-\\frac{2}{\\sin\\alpha\\cos\\alpha}=4\">\\lvert PA\\rvert\\lvert PB\\rvert\n=-\\frac{2}{\\sin\\alpha\\cos\\alpha}=4</div> 即 <span class=\"gk-math\" data-tex=\"\\sin2\\alpha=-1\">\\sin2\\alpha=-1</span>. 结合 <span class=\"gk-math\" data-tex=\"\\dfrac\\pi2&lt;\\alpha&lt;\\pi\">\\dfrac\\pi2&lt;\\alpha&lt;\\pi</span>，得 <span class=\"gk-math\" data-tex=\"\\alpha=\\dfrac{3\\pi}{4}\">\\alpha=\\dfrac{3\\pi}{4}</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"\\tan\\alpha=-1\">\\tan\\alpha=-1</span> 且直线过点 <span class=\"gk-math\" data-tex=\"P(2,1)\">P(2,1)</span>，得直线方程 <span class=\"gk-math\" data-tex=\"y-1=-(x-2)\">y-1=-(x-2)</span>，即 <span class=\"gk-math\" data-tex=\"x+y-3=0\">x+y-3=0</span>. 在极坐标中 <span class=\"gk-math\" data-tex=\"x=\\rho\\cos\\theta\">x=\\rho\\cos\\theta</span>，<span class=\"gk-math\" data-tex=\"y=\\rho\\sin\\theta\">y=\\rho\\sin\\theta</span>，所以 <span class=\"gk-math\" data-tex=\"l\">l</span> 的极坐标方程为 <span class=\"gk-math\" data-tex=\"\\rho\\cos\\theta+\\rho\\sin\\theta-3=0\">\\rho\\cos\\theta+\\rho\\sin\\theta-3=0</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2023-national_paper_a_science-q23","paperId":"2023-national_paper_a_science","number":23,"type":"written","score":10,"lessonIds":["2.1","3.1"],"difficulty":"进阶","hint":"这是旧课标不等式选讲，超出当前五册；先在 x<a 与 x≥a 两段去掉绝对值，再画出 V 形图找三角形面积。","legacy":true,"legacyReason":"","searchText":"设 a>0 ，函数 f(x)=2\\lvert x-a \\rvert-a . 求不等式 f(x)<x 的解集； 若曲线 y=f(x) 与 x 轴所围成的图形的面积为 2，求 a . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，函数 <span class=\"gk-math\" data-tex=\"f(x)=2\\lvert x-a \\rvert-a\">f(x)=2\\lvert x-a \\rvert-a</span>.<br><br><ol class=\"gk-subparts\"><li>求不等式 <span class=\"gk-math\" data-tex=\"f(x)&lt;x\">f(x)&lt;x</span> 的解集；</li><li>若曲线 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 与 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴所围成的图形的面积为 2，求 <span class=\"gk-math\" data-tex=\"a\">a</span>.</li></ol>","optionsHtml":[],"answerHtml":"<span>见下方分步解析</span>","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"x&lt;a\">x&lt;a</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=a-2x\">f(x)=a-2x</span>，不等式 <span class=\"gk-math\" data-tex=\"f(x)&lt;x\">f(x)&lt;x</span> 等价于 <span class=\"gk-math\" data-tex=\"x&gt;\\dfrac a3\">x&gt;\\dfrac a3</span>，与 <span class=\"gk-math\" data-tex=\"x&lt;a\">x&lt;a</span> 合并得 <span class=\"gk-math\" data-tex=\"\\dfrac a3&lt;x&lt;a\">\\dfrac a3&lt;x&lt;a</span>. 当 <span class=\"gk-math\" data-tex=\"x\\geq a\">x\\geq a</span> 时，<span class=\"gk-math\" data-tex=\"f(x)=2x-3a\">f(x)=2x-3a</span>，不等式等价于 <span class=\"gk-math\" data-tex=\"x&lt;3a\">x&lt;3a</span>，与 <span class=\"gk-math\" data-tex=\"x\\geq a\">x\\geq a</span> 合并得 <span class=\"gk-math\" data-tex=\"a\\leq x&lt;3a\">a\\leq x&lt;3a</span>. 因为 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，所以解集为 <span class=\"gk-math\" data-tex=\"\\left(\\dfrac a3,3a\\right)\">\\left(\\dfrac a3,3a\\right)</span>.</li><li>令 <span class=\"gk-math\" data-tex=\"f(x)=0\">f(x)=0</span>，得 <span class=\"gk-math\" data-tex=\"2\\lvert x-a\\rvert-a=0\">2\\lvert x-a\\rvert-a=0</span>，所以曲线与 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴的交点横坐标为 <span class=\"gk-math\" data-tex=\"x=\\dfrac a2\">x=\\dfrac a2</span> 和 <span class=\"gk-math\" data-tex=\"x=\\dfrac{3a}{2}\">x=\\dfrac{3a}{2}</span>. 在区间 <span class=\"gk-math\" data-tex=\"\\left[\\dfrac a2,a\\right]\">\\left[\\dfrac a2,a\\right]</span> 和 <span class=\"gk-math\" data-tex=\"\\left[a,\\dfrac{3a}{2}\\right]\">\\left[a,\\dfrac{3a}{2}\\right]</span> 上，曲线位于 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴下方，且两部分分别为底边长 <span class=\"gk-math\" data-tex=\"\\dfrac a2\">\\dfrac a2</span>、高 <span class=\"gk-math\" data-tex=\"a\">a</span> 的三角形. 因此所围图形面积为 <div class=\"gk-math display\" data-tex=\"S=\\frac12\\cdot\\frac a2\\cdot a+\\frac12\\cdot\\frac a2\\cdot a=\\frac{a^2}{2}\">S=\\frac12\\cdot\\frac a2\\cdot a+\\frac12\\cdot\\frac a2\\cdot a=\\frac{a^2}{2}</div> 由 <span class=\"gk-math\" data-tex=\"S=2\">S=2</span> 且 <span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，得 <span class=\"gk-math\" data-tex=\"a^2=4\">a^2=4</span>，所以 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
